import {renderDiagram}from './visual.js?v=20261023-physicscomplete01';
import {chromosomeFigure,cycleFigure}from './division-figures.js?v=20261023-physicscomplete01';
import {chromosomeChallenges,chromosomeIDs,copyIDs,allocationValid,nucleusInventory,stageIndex}from './division-models.js?v=20261023-physicscomplete01';
import {escapeLab}from './catalog-labs.js?v=20261023-physicscomplete01';
export function showChromosomes(level='nucleus',w={}){renderDiagram('Chromosomes, DNA & genes',level==='gene'?'A gene is a section of DNA':level==='nucleus'?'Two illustrative chromosome pairs':level==='chromosome'?'Many genes along one chromosome':'DNA molecule · selected region',chromosomeFigure({level,region:w.region||'A'})+'<p class="diagram-caption">Symbolic zoom levels use different scales. Rods represent unreplicated chromosomes; only a few illustrative gene regions are highlighted.</p>','EXPLORE THE GENETIC MATERIAL');}
export function showCycle(stage=0,w={}){stage=stageIndex(stage);renderDiagram(['Prepare to divide','Copy the DNA','Allocate complete sets','Divide the cell contents','Two daughter cells'][stage],stage===0&&w.grown?'Growth and more sub-cellular structures':'Three overall stages · five teaching snapshots',cycleFigure({stage,assignments:stage===2?w.assignments:null,grown:w.grown})+'<p class="diagram-caption">Four chromosomes are a small teaching example. Nuclear outlines in allocation mode are targets, not a time-lapse. Rods, colours and timing are symbolic; these are not named mitosis phases.</p>','TRACK A COMPLETE SET INTO EACH CELL');}
const optionHTML=(options,answer)=>'<option value="">Choose…</option>'+options.map(([value,label])=>'<option value="'+escapeLab(value)+'"'+(answer===value?' selected':'')+'>'+escapeLab(label)+'</option>').join('');
export function mountDivision(l,p,root,{save,done,feedback}){
 const w=p.widget,$=s=>root.querySelector(s);w.task??=0;w.passed??=[];
 const complete=(id,total)=>{if(!w.passed.includes(id))w.passed.push(id);if(w.passed.length===total){p.widgetDone=true;save();done();}save();$('#divisionProgress').textContent=w.passed.length+' / '+total+' complete';};
 if(l.widget==='chromosome-map'){
  w.level??='nucleus';w.region??='A';w.visited??=['nucleus'];w.answers??={};const t=chromosomeChallenges[w.task%3];
  root.innerHTML='<p><b>'+(w.task+1)+' / 3 · '+t.title+'</b></p><p>'+t.prompt+'</p><div class="model-actions">'+['nucleus','chromosome','dna','gene'].map(level=>'<button class="secondary" data-genome="'+level+'" aria-pressed="'+(w.level===level)+'">'+({nucleus:'Nucleus',chromosome:'Chromosome',dna:'DNA',gene:'Gene close-up'}[level])+'</button>').join('')+'</div><label class="field-label" for="geneRegion">Highlight an illustrative gene region</label><select class="lab-select" id="geneRegion">'+optionHTML([['A','Region A'],['B','Region B'],['C','Region C']],w.region)+'</select><label class="field-label" for="chromosomeAnswer">Explain the structure</label><select class="lab-select" id="chromosomeAnswer">'+optionHTML(t.options,w.answers[t.id])+'</select><button class="secondary" id="checkDivision">Check explanation</button><button class="secondary" id="nextDivision">Next challenge →</button><p id="divisionProgress">'+w.passed.length+' / 3 complete</p>';
  const draw=()=>showChromosomes(w.level,w);for(const b of root.querySelectorAll('[data-genome]'))b.onclick=()=>{w.level=b.dataset.genome;if(!w.visited.includes(w.level))w.visited.push(w.level);save();for(const e of root.querySelectorAll('[data-genome]'))e.setAttribute('aria-pressed',String(e.dataset.genome===w.level));draw();};
  $('#geneRegion').onchange=e=>{w.region=e.target.value;if(w.region==='B')w.regionB=true;save();draw();};$('#chromosomeAnswer').onchange=e=>{w.answers[t.id]=e.target.value;save();};
  $('#checkDivision').onclick=()=>{if(!t.views.every(v=>w.visited.includes(v))||(t.id==='gene'&&!w.regionB)){feedback('Explore the requested views'+(t.id==='gene'?' and highlight region B':'')+' before explaining.',true);return;}if(w.answers[t.id]!==t.answer){feedback(t.why,true);return;}feedback(t.why);complete(t.id,3);};
  $('#nextDivision').onclick=()=>{if(!w.passed.includes(t.id)){feedback('Complete this exploration and explanation first.',true);return;}w.task=(w.task+1)%3;save();feedback('');mountDivision(l,p,root,{save,done,feedback});};draw();return;
 }
 w.assignments??={};w.stage??=0;const task=w.task%3;
 const shared='<button class="secondary" id="checkDivision">Check reasoning</button><button class="secondary" id="nextDivision">Next challenge →</button><p id="divisionProgress">'+w.passed.length+' / 3 complete</p>';
 if(task===0){root.innerHTML='<p><b>1 / 3 · Prepare the cell</b></p><p>Grow the cell and increase its sub-cellular structures, then copy the DNA before mitosis.</p><div class="model-actions"><button class="secondary" id="growCell">Grow and make structures</button><button class="secondary" id="copyDNA">Copy DNA</button></div><p class="micro-note" id="prepareStatus"></p><label class="field-label" for="copyTiming">DNA copying happens…</label><select class="lab-select" id="copyTiming">'+optionHTML([['before','Before mitosis'],['after','Only after the new cells separate'],['during','Only when the nucleus has already divided']],w.timing)+'</select>'+shared;
  const draw=()=>{showCycle(w.copied?1:0,w);$('#prepareStatus').textContent=(w.grown?'Growth/structures ready':'Growth still needed')+' · '+(w.copied?'DNA copied:4 originals represented by8 copies':'DNA not copied:4 original copies');};
  $('#growCell').onclick=()=>{w.grown=true;save();draw();};$('#copyDNA').onclick=()=>{if(!w.grown){feedback('Prepare the cell by growing and increasing structures first.',true);return;}w.copied=true;w.stage=1;save();draw();};$('#copyTiming').onchange=e=>{w.timing=e.target.value;save();};
  $('#checkDivision').onclick=()=>{if(!w.grown||!w.copied){feedback('Use the model to prepare the cell and copy the DNA first.',true);return;}if(w.timing!=='before'){feedback('DNA replicates before mitosis. Mitosis separates the copied genetic material and divides the nucleus.',true);return;}feedback('Growth, more structures and copied DNA prepare the cell for mitosis.');complete('prepare',3);};draw();
 }else if(task===1){root.innerHTML='<p><b>2 / 3 · Build two complete genetic sets</b></p><p>Each original chromosome has two matching copies (a and b). Allocate one copy of A1, A2, B1 and B2 to each nucleus. Equal totals alone are not enough.</p><div class="copy-allocation">'+chromosomeIDs.map(id=>'<fieldset class="copy-row"><legend>'+id+' copies</legend>'+['a','b'].map(c=>'<label class="field-label" for="assign-'+id+'-'+c+'">Copy '+id+'.'+c+'<select class="lab-select" id="assign-'+id+'-'+c+'" data-copy="'+id+'.'+c+'">'+optionHTML([['L','Nucleus 1'],['R','Nucleus 2']],w.assignments[id+'.'+c])+'</select></label>').join('')+'</fieldset>').join('')+'</div><p class="micro-note" id="allocationStatus"></p>'+shared;
  const draw=()=>{showCycle(2,w);$('#allocationStatus').textContent='Nucleus1: '+(nucleusInventory(w.assignments,'L').join(', ')||'none')+' · Nucleus2: '+(nucleusInventory(w.assignments,'R').join(', ')||'none')+' · Unassigned: '+copyIDs.filter(id=>!w.assignments[id]).length;};
  for(const el of root.querySelectorAll('[data-copy]'))el.onchange=e=>{w.assignments[el.dataset.copy]=e.target.value;save();draw();};$('#checkDivision').onclick=()=>{if(!w.copied||!w.passed.includes('prepare')){feedback('Complete DNA copying in the preparation challenge first.',true);return;}if(!allocationValid(w.assignments)){feedback('Each nucleus needs one A1, one A2, one B1 and one B2. Check for missing or duplicated identities as well as totals.',true);return;}w.stage=2;save();feedback('Both nuclei receive the same complete set. The nucleus divides during mitosis; the cell contents still need to divide.');complete('allocate',3);};draw();
 }else{root.innerHTML='<p><b>3 / 3 · Finish cell division</b></p><p>Predict the result before splitting the cytoplasm and membrane. The model started with4 chromosomes.</p><label class="field-label" for="daughterCount">Chromosomes in EACH completed daughter cell</label><input class="lab-input" type="number" step="1" id="daughterCount" value="'+escapeLab(w.count??'')+'"><label class="field-label" for="daughterSet">Genetic material in the two daughter cells</label><select class="lab-select" id="daughterSet">'+optionHTML([['same','Genetically identical complete sets in this model'],['half','Different incomplete halves'],['none','No genetic material']],w.set)+'</select><button class="secondary" id="splitCell">Step cell-content division →</button><p class="micro-note" id="splitStatus"></p>'+shared;
  const draw=()=>{showCycle(Math.max(2,w.stage),w);$('#splitStatus').textContent=w.stage===4?'Two daughter cells formed':w.stage===3?'Cell contents dividing':'Nuclei ready; cell contents not yet divided';};$('#daughterCount').oninput=e=>{w.count=e.target.value;save();};$('#daughterSet').onchange=e=>{w.set=e.target.value;save();};
  $('#splitCell').onclick=()=>{if(!w.passed.includes('allocate')||!allocationValid(w.assignments)){feedback('Complete the allocation challenge first.',true);return;}if(String(w.count??'').trim()===''||!w.set){feedback('Predict the chromosome count and genetic result before splitting.',true);return;}w.stage=Math.min(4,Math.max(2,w.stage)+1);save();draw();};$('#checkDivision').onclick=()=>{if(w.stage!==4){feedback('Take the model through cell-content division to two completed cells first.',true);return;}if(Number(w.count)!==4||w.set!=='same'){feedback('Each daughter receives one complete set of4 chromosomes. DNA was copied first, so mitosis does not halve the original set.',true);return;}feedback('Two genetically identical daughter cells retain the original chromosome set in this model. Cell division supports growth, development and repair.');complete('divide',3);};draw();
 }
 $('#nextDivision').onclick=()=>{const id=['prepare','allocate','divide'][task];if(!w.passed.includes(id)){feedback('Complete this challenge before continuing.',true);return;}w.task=(w.task+1)%3;save();feedback('');mountDivision(l,p,root,{save,done,feedback});};
}
